+                    localRef.get().getIndexExpression(),
+                    SearchResponse.Cluster.Status.PARTIAL,
+                    5,
+                    2,
+                    1,
+                    3,
+                    Collections.emptyList(),
+                    new TimeValue(1000),
+                    false
+                );
+                partial--;
+            }
