+            } else if (skipped > 0) {
+                updated = new SearchResponse.Cluster(
+                    clusterAlias,
+                    clusterRef.get().getIndexExpression(),
+                    SearchResponse.Cluster.Status.SKIPPED,
+                    5,
+                    0,
+                    0,
+                    5,
+                    Collections.emptyList(),
+                    new TimeValue(1000),
+                    false
+                );
+                skipped--;
+            } else {
